        Arrays.fill(map, -1);
        int start = 0;
        int max = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (map[c] != -1 && map[c] >= start) {
                max = Math.max(max, i - start);
